class Solution {
    public int countSegments(String s) {
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != ' ' && (i == 0 || s.charAt(i - 1) == ' ')) {
                count++;
            }
        }
        return count;
    }
}

class Solution {
    public int countSegments(String s) {
        s = s.trim();
        if (s.length() == 0) return 0;
        String[] parts = s.split("\\s+");
        return parts.length;
    }
}
